+package com.example;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void emptySendShowsValidationErrors() {
+        page.navigate(getUrl() + "/contact");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        assertTrue(send.isEnabled());
+
+        send.click();
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        name.assertErrorMessage("Name is required");
+        email.assertErrorMessage("Give an e-mail address or a phone number");
+        message.assertErrorMessage("Message is required");
+    }
+
+    @Test
+    void validSendClearsFormShowsNotificationAndDisablesSend() {
+        page.navigate(getUrl() + "/contact");
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+
+        name.setValue("Playwright Pete");
+        email.setValue("pete@example.com");
+        message.setValue("Testing in a real browser");
+        send.click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        send.assertDisabled();
+
+        name.setValue("x");
+        send.assertEnabled();
+
+        GridElement grid = GridElement.get(page);
+        assertTrue(grid.getRenderedRowCount() >= 1);
+    }
+
+    @Test
+    void navigatingAwayWithEmptyFormProceedsImmediately() {
+        page.navigate(getUrl() + "/contact");
+        page.getByText("About").click();
+        waitUntil(() -> "About".equals(page.locator("h1").first().textContent()));
+    }
+
+    @Test
+    void navigatingAwayWithDataAsksAndKeepEditingCancels() {
+        page.navigate(getUrl() + "/contact");
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Someone");
+
+        page.getByText("About").click();
+        waitUntil(() -> page.locator("vaadin-dialog[opened]").count() == 1);
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        waitUntil(() -> page.locator("vaadin-dialog[opened]").count() == 0);
+
+        assertEquals("Someone", name.getValue());
+        assertEquals(getUrl() + "/contact", page.url());
+    }
+
+    @Test
+    void navigatingAwayWithDataDiscardProceeds() {
+        page.navigate(getUrl() + "/contact");
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Someone else");
+
+        page.getByText("About").click();
+        waitUntil(() -> page.locator("vaadin-dialog[opened]").count() == 1);
+
+        ButtonElement.getByText(page, "Discard").click();
+        waitUntil(() -> "About".equals(page.locator("h1").first().textContent()));
+    }
+
+    private void waitUntil(java.util.function.BooleanSupplier condition) {
+        long deadline = System.currentTimeMillis() + 10000;
+        while (System.currentTimeMillis() < deadline) {
+            if (condition.getAsBoolean()) {
+                return;
+            }
+            page.waitForTimeout(100);
+        }
+        assertTrue(condition.getAsBoolean(), "condition not met within timeout");
+    }
+}
